function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 values.';
  // Deterministic Miller-Rabin with bases 2, 7 and 61 is exact below 4,759,123,141.
  const mulMod = (a, b, m) => ((a * Math.floor(b / 65536)) % m * 65536 + a * (b % 65536)) % m;
  const powMod = (base, exp, m) => {
    let result = 1;
    base %= m;
    while (exp > 0) {
      if (exp % 2 === 1) result = mulMod(result, base, m);
      base = mulMod(base, base, m);
      exp = Math.floor(exp / 2);
    }
    return result;
  };
  const isPrime = n => {
    for (const p of [2, 3, 5, 7, 11, 13, 61]) if (n % p === 0) return n === p;
    let d = n - 1, s = 0;
    while (d % 2 === 0) { d /= 2; s++; }
    for (const a of [2, 7, 61]) {
      let x = powMod(a, d, n);
      if (x === 1 || x === n - 1) continue;
      let composite = true;
      for (let r = 1; r < s && composite; r++) { x = mulMod(x, x, n); if (x === n - 1) composite = false; }
      if (composite) return false;
    }
    return true;
  };
  for (const v of nums) {
    if (!Number.isInteger(v) || v < 2 || v > 1e9) return 'Each value is an integer from 2 to 10^9.';
    if (!isPrime(v)) return `${v} is not prime; every value must be a prime.`;
  }
  return null;
}

