function minBitwiseArray(nums) {
  const ans = [];
  for (const num of nums) {
    if ((num & 1) === 0) {
      ans.push(-1);
    } else {
      const lowestZero = (num + 1) & ~num;
      ans.push(num ^ (lowestZero >> 1));
    }
  }
  return ans;
}

