function minBitwiseArray(nums) {
  // a | (a + 1) is a plus one power of two, so every valid a is num minus a power of two:
  // test each such candidate against the definition and keep the smallest that works.
  return nums.map(num => {
    let smallest = -1;
    for (let power = 1; power <= num; power *= 2) {
      const a = num - power;
      if ((a | (a + 1)) === num && (smallest === -1 || a < smallest)) smallest = a;
    }
    return smallest;
  });
}

