function generate(rand, size) {
  const isPrime = n => {
    if (n < 2) return false;
    if (n % 2 === 0) return n === 2;
    for (let d = 3; d * d <= n; d += 2) if (n % d === 0) return false;
    return true;
  };
  const randomPrime = limit => {
    for (;;) {
      const n = 2 + Math.floor(rand() * (limit - 1));
      if (isPrime(n)) return n;
    }
  };
  // Primes ending in a long run of one bits have answers far below themselves.
  const onesPrime = limit => {
    const most = Math.floor(Math.log2(limit));
    for (;;) {
      const t = 2 + Math.floor(rand() * (most - 2));
      const high = Math.floor(rand() * Math.floor(limit / 2 ** t));
      const n = high * 2 ** t + 2 ** t - 1;
      if (isPrime(n)) return n;
    }
  };
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const limit = size === 'large' || rand() < 0.3 ? 1e9 : 300;
  const nums = [];
  for (let i = 0; i < n; i++) {
    const r = rand();
    nums.push(r < 0.1 ? 2 : r < 0.4 ? onesPrime(limit) : randomPrime(limit));
  }
  if (n > 1 && rand() < 0.15) nums[n - 1] = nums[0];
  return [nums];
}
